#include <Arduino.h>
#include <Wire.h>
#include <Preferences.h>
#include <Adafruit_GFX.h>
#include <Adafruit_SSD1306.h>
#include <NimBLEDevice.h>
#include <math.h>

#define SDA_PIN 8
#define SCL_PIN 9
#define ADC_PIN 0
#define UP_PIN 3
#define DOWN_PIN 4
#define OK_PIN 5
#define OLED_ADDR 0x3C
#define SWVER 3

const float RTOP=22000.0f, RBOT=10000.0f;
const float DIV=(RTOP+RBOT)/RBOT;
const float ADC_REF=3.30f;
const float DEFAULT_CAP=42.0f;
const float LOW_L=5.0f;
const float MIN_SPAN=0.10f;
const uint32_t STABLE_MS=2500;

Adafruit_SSD1306 oled(128,64,&Wire,-1);
Preferences nvs;

float capacityL=DEFAULT_CAP;
float calV[5]={0.80,1.70,2.50,3.40,4.50};
float rawV=0, filtV=NAN, litres=0;
bool sensorOK=false, openWire=false, stable=false;
uint32_t stableSince=0,lastDraw=0,lastTx=0,lastSample=0;
float history[8]={0}; int hp=0;

enum UI {MAIN,MENU,CAP,CAL,INFO}; UI ui=MAIN;
int mi=0, ci=0;

const char* SERVICE="7d7a0000-5f6e-4a9e-8b1c-000000000001";
const char* TX="7d7a0001-5f6e-4a9e-8b1c-000000000001";
const char* RX="7d7a0002-5f6e-4a9e-8b1c-000000000001";
NimBLECharacteristic* txc=nullptr;

float readV(){
 uint32_t s=0;
 for(int i=0;i<48;i++){s+=analogRead(ADC_PIN);delayMicroseconds(200);}
 return (s/48.0f)*ADC_REF/4095.0f*DIV;
}
bool validCal(){
 if(calV[4]-calV[0]<MIN_SPAN)return false;
 for(int i=1;i<5;i++)if(calV[i]<=calV[i-1])return false;
 return true;
}
void derive(){
 if(calV[4]>calV[0]+MIN_SPAN)
   for(int i=1;i<4;i++)calV[i]=calV[0]+(calV[4]-calV[0])*i/4.0f;
}
float toLitres(float v){
 if(!validCal())return NAN;
 if(v<=calV[0])return 0;
 if(v>=calV[4])return capacityL;
 for(int i=0;i<4;i++)if(v>=calV[i]&&v<=calV[i+1]){
   float t=(v-calV[i])/(calV[i+1]-calV[i]);
   return capacityL*(i+t)/4.0f;
 }
 return NAN;
}
void save(){
 nvs.begin("lpg3",false);
 nvs.putUChar("ver",SWVER); nvs.putFloat("cap",capacityL);
 for(int i=0;i<5;i++){char k[5];sprintf(k,"v%d",i);nvs.putFloat(k,calV[i]);}
 nvs.end();
}
void load(){
 nvs.begin("lpg3",true);
 if(nvs.getUChar("ver",0)!=SWVER){nvs.end();save();return;}
 capacityL=nvs.getFloat("cap",DEFAULT_CAP);
 for(int i=0;i<5;i++){char k[5];sprintf(k,"v%d",i);calV[i]=nvs.getFloat(k,calV[i]);}
 nvs.end();
 if(capacityL<1||capacityL>200)capacityL=DEFAULT_CAP;
 if(!validCal()){calV[0]=0.8;calV[1]=1.7;calV[2]=2.5;calV[3]=3.4;calV[4]=4.5;}
}
void telemetry(){
 if(!txc)return;
 char b[300]; float pct=capacityL?litres*100/capacityL:0;
 snprintf(b,sizeof(b),"{\"liters\":%.2f,\"percent\":%.1f,\"voltage\":%.3f,\"capacity\":%.1f,\"sensor\":%s,\"open\":%s,\"stable\":%s,\"calValid\":%s}",
 litres,pct,filtV,capacityL,sensorOK?"true":"false",openWire?"true":"false",stable?"true":"false",validCal()?"true":"false");
 txc->setValue((uint8_t*)b,strlen(b));txc->notify();
}
class CB:public NimBLECharacteristicCallbacks{
 void onWrite(NimBLECharacteristic*c,NimBLEConnInfo&)override{
  std::string s=c->getValue();
  if(s=="GET"){telemetry();return;}
  if(s=="SAVE"){save();return;}
  if(s=="RESET_CAL"){calV[0]=.8;calV[1]=1.7;calV[2]=2.5;calV[3]=3.4;calV[4]=4.5;save();return;}
  if(s=="CAL_START"){ci=0;ui=CAL;return;}
  if(s=="CAL_CANCEL"){ui=MAIN;return;}
  if(s=="CAL_CAPTURE"&&ui==CAL&&stable){
    calV[ci]=filtV;
    if(ci==4){if(validCal()||calV[4]>calV[0]+MIN_SPAN){derive();save();ui=MAIN;}}
    else ci++;
    return;
  }
  if(s.rfind("SET_CAP:",0)==0){float x=atof(s.c_str()+8);if(x>=1&&x<=200){capacityL=x;save();}return;}
 }
};
void ble(){
 NimBLEDevice::init("WPGH-1 LPG Meter V3");
 auto*ser=NimBLEDevice::createServer()->createService(SERVICE);
 txc=ser->createCharacteristic(TX,NIMBLE_PROPERTY::READ|NIMBLE_PROPERTY::NOTIFY);
 auto*rx=ser->createCharacteristic(RX,NIMBLE_PROPERTY::WRITE|NIMBLE_PROPERTY::WRITE_NR);
 rx->setCallbacks(new CB());ser->start();
 auto*a=NimBLEDevice::getAdvertising();a->addServiceUUID(SERVICE);a->start();
}
void mainUI(){
 oled.clearDisplay();oled.setTextColor(1);oled.setTextSize(4);
 char b[12];sprintf(b,"%.0f",litres);int16_t x,y;uint16_t w,h;oled.getTextBounds(b,0,0,&x,&y,&w,&h);
 oled.setCursor((128-w)/2,2);oled.print(b);
 oled.setTextSize(1);oled.setCursor(0,39);
 if(openWire)oled.print("SENSOR OPEN/ERROR");
 else if(litres<=LOW_L)oled.print((millis()/500)%2?"LOW GAS":"");
 else oled.print("WPGH-1");
 oled.drawRect(6,54,116,7,1);int f=(int)(114*constrain(litres/capacityL,0.0f,1.0f));oled.fillRect(7,55,f,5,1);oled.display();
}
void menuUI(){
 const char*m[]={"CAPACITY","5-POINT CAL","INFO","SAVE","EXIT"};
 oled.clearDisplay();oled.setTextSize(1);
 for(int i=0;i<5;i++){oled.setCursor(0,i*12);oled.print(i==mi?"> ":"  ");oled.print(m[i]);}
 oled.display();
}
void calUI(){
 oled.clearDisplay();oled.setTextSize(1);
 oled.setCursor(0,0);oled.print("CAL ");oled.print(ci*25);oled.print("%");
 oled.setCursor(0,14);oled.print("V=");oled.print(filtV,3);oled.print(" V");
 oled.setCursor(0,27);oled.print(stable?"STABLE":"WAIT STABLE");
 oled.setCursor(0,43);oled.print("OK: CAPTURE");
 oled.setCursor(0,55);oled.print("Point ");oled.print(ci+1);oled.print("/5");
 oled.display();
}
void capUI(){
 oled.clearDisplay();oled.setTextSize(1);oled.setCursor(0,0);oled.print("TANK CAPACITY");
 oled.setTextSize(3);oled.setCursor(25,20);oled.print(capacityL,0);oled.print("L");
 oled.setTextSize(1);oled.setCursor(0,55);oled.print("UP/DOWN OK=SAVE");oled.display();
}
bool key(int p){return digitalRead(p)==LOW;}
void buttons(){
 static uint32_t last=0;if(millis()-last<180)return;
 bool u=key(UP_PIN),d=key(DOWN_PIN),o=key(OK_PIN);
 if(ui==MAIN&&o){ui=MENU;mi=0;last=millis();return;}
 if(ui==MENU){
  if(u){mi=(mi+4)%5;last=millis();}
  else if(d){mi=(mi+1)%5;last=millis();}
  else if(o){if(mi==0)ui=CAP;else if(mi==1){ci=0;ui=CAL;}else if(mi==2)ui=INFO;else if(mi==3)save();else ui=MAIN;last=millis();}
 }else if(ui==CAP){
  if(u){capacityL++;if(capacityL>200)capacityL=1;last=millis();}
  else if(d){capacityL--;if(capacityL<1)capacityL=200;last=millis();}
  else if(o){save();ui=MENU;last=millis();}
 }else if(ui==CAL&&o){
  if(stable){calV[ci]=filtV;if(ci==4){derive();if(validCal())save();ui=MAIN;}else ci++;}
  last=millis();
 }else if(ui==INFO&&o){ui=MENU;last=millis();}
}
void setup(){
 pinMode(UP_PIN,INPUT_PULLUP);pinMode(DOWN_PIN,INPUT_PULLUP);pinMode(OK_PIN,INPUT_PULLUP);
 analogReadResolution(12);Wire.begin(SDA_PIN,SCL_PIN);oled.begin(SSD1306_SWITCHCAPVCC,OLED_ADDR);oled.clearDisplay();oled.display();
 load();ble();
}
void loop(){
 if(millis()-lastSample>=100){lastSample=millis();rawV=readV();history[hp++%8]=rawV;
   float avg=0;for(float x:history)avg+=x;avg/=8;
   openWire=(avg<0.03||avg>5.5);sensorOK=!openWire;
   if(!isfinite(filtV))filtV=avg;float a=avg>filtV?.14:.02;filtV+=a*(avg-filtV);
   float mn=100,mx=-100;for(float x:history){mn=min(mn,x);mx=max(mx,x);}
   if(mx-mn<0.025){if(!stable)stableSince=millis();stable=true;}else stable=false;
   litres=toLitres(filtV);if(!isfinite(litres))litres=0;
 }
 buttons();
 if(millis()-lastDraw>150){lastDraw=millis();if(ui==MAIN)mainUI();else if(ui==MENU)menuUI();else if(ui==CAP)capUI();else if(ui==CAL)calUI();else {oled.clearDisplay();oled.setTextSize(1);oled.setCursor(0,0);oled.print("WPGH-1 V3");oled.setCursor(0,14);oled.printf("V %.3f",filtV);oled.setCursor(0,27);oled.printf("L %.1f",litres);oled.setCursor(0,40);oled.printf("CAP %.1f",capacityL);oled.setCursor(0,53);oled.print(validCal()?"CAL OK":"CAL ERROR");oled.display();}}
 if(millis()-lastTx>500){lastTx=millis();telemetry();}
 delay(5);
}
